'use strict';
// Rival Routes v1: offline, unverified friend challenges; ghosts never affect physics.
const R=(()=>{
const VERSION=1,SECONDS=75,MAX_SAMPLES=752;
let active=false,seed=1,world=0,rng=1,samples=[],ghost=null,lastRun=null,nextSample=0;
function random(){rng=(Math.imul(rng,1664525)+1013904223)>>>0;return rng/4294967296}
function code(){return `HW1-${world}-${seed.toString(36).toUpperCase()}`}
function parse(text){const m=/^HW1-([0-4])-([0-9A-Z]{1,7})$/i.exec(text.trim());if(!m)throw Error('Use a code like HW1-0-123ABC.');const n=parseInt(m[2],36);if(!Number.isSafeInteger(n)||n<1||n>4294967295)throw Error('Challenge seed is invalid.');return{world:+m[1],seed:n}}
function configure(text){const c=parse(text);world=c.world;seed=c.seed;active=true}
function begin(){rng=seed;samples=[];nextSample=0}
function capture(){if(!active||samples.length>=MAX_SAMPLES||elapsed+1e-6<nextSample)return;samples.push([+elapsed.toFixed(3),+player.x.toFixed(2),+player.y.toFixed(2),+player.a.toFixed(4)]);nextSample+=.1}
function validate(run){if(!run||run.version!==VERSION)throw Error('Unsupported ghost version.');const c=parse(run.code);if(run.code!==`HW1-${c.world}-${c.seed.toString(36).toUpperCase()}`)throw Error('Invalid ghost code.');if(!Number.isFinite(run.time)||run.time<0||run.time>SECONDS+.1||!Number.isInteger(run.score)||run.score<0||run.score>10000000||typeof run.success!=='boolean')throw Error('Invalid result.');if(!Array.isArray(run.samples)||!run.samples.length||run.samples.length>MAX_SAMPLES)throw Error('Invalid ghost length.');let previous=-1;for(const p of run.samples){if(!Array.isArray(p)||p.length!==4||!p.every(Number.isFinite)||p[0]<=previous||p[0]<0||p[0]>run.time+.1||Math.abs(p[1])>800||Math.abs(p[2])>800||Math.abs(p[3])>10000)throw Error('Invalid ghost path.');previous=p[0]}return run}
function finish(success){if(!active)return;capture();lastRun={version:VERSION,code:code(),time:+elapsed.toFixed(3),score:Math.floor(score),success,samples:samples.map(p=>p.slice())};$('overTag').textContent='RIVAL ROUTES · LOCAL / UNVERIFIED';$('overTitle').textContent=success?'ROUTE CLEARED!':'TRY THAT AGAIN.';const rival=ghost&&ghost.code===code()?` · Recorded rival: ${ghost.score.toLocaleString()} points`:'';$('summary').textContent=`${code()} · ${elapsed.toFixed(1)}s · ${Math.floor(score).toLocaleString()} points${rival}. Standard Dust Devil. No campaign rewards.`;$('again').textContent='REMATCH SAME ROUTE ↗';$('again').onclick=()=>start();$('rivalResults').hidden=false}
function draw(ctx){if(!active||!ghost||ghost.code!==code()||elapsed>ghost.time)return;const path=ghost.samples;let i=Math.min(path.length-1,Math.floor(elapsed*10));while(i>0&&path[i][0]>elapsed)i--;while(i+1<path.length&&path[i+1][0]<elapsed)i++;const a=path[i],b=path[Math.min(i+1,path.length-1)],f=b[0]>a[0]?Math.max(0,Math.min(1,(elapsed-a[0])/(b[0]-a[0]))):0;ctx.save();ctx.translate(a[1]+(b[1]-a[1])*f,a[2]+(b[2]-a[2])*f);ctx.rotate(a[3]+angleDiff(b[3],a[3])*f+Math.PI/2);ctx.globalAlpha=.55;ctx.fillStyle='#68f4e2';ctx.fillRect(-13,-27,26,51);ctx.fillStyle='#153d47';ctx.fillRect(-9,-10,18,15);ctx.restore();ctx.save();ctx.fillStyle='#b5fff4';ctx.font='bold 10px sans-serif';ctx.textAlign='center';ctx.fillText('RECORDED GHOST',a[1],a[2]-38);ctx.restore()}
function download(blob,name){if(window.RunroadFiles){const reader=new FileReader();reader.onload=()=>window.RunroadFiles.postMessage(JSON.stringify({name,mime:blob.type,data:reader.result.split(',')[1]}));reader.readAsDataURL(blob);return}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function show(){const d=$('rivalDialog');$('rivalCode').value=code();$('rivalStatus').textContent=ghost?`Recorded ghost loaded · ${ghost.code}`:'Create a route or enter a friend’s code. Import their ghost file to see their recorded drive.';d.showModal()}
function message(text){$('rivalStatus').textContent=text}
async function share(){if(!lastRun)return;const text=`Can you escape my RUNROAD route? ${lastRun.code} · ${lastRun.score} points. Open Rival Routes and enter the code. Import my ghost file to race my recorded drive.`;try{if(navigator.share)await navigator.share({title:'RUNROAD · Rival Routes',text});else if(navigator.clipboard){await navigator.clipboard.writeText(text);$('rivalResultStatus').textContent='Challenge copied. Send the ghost file separately.'}else $('rivalResultStatus').textContent=text}catch(e){if(e.name!=='AbortError')$('rivalResultStatus').textContent=text}}
function card(){if(!lastRun)return;const c=document.createElement('canvas');c.width=900;c.height=600;const x=c.getContext('2d');x.fillStyle='#15262c';x.fillRect(0,0,900,600);x.fillStyle='#ff7845';x.font='bold 56px sans-serif';x.fillText('RUNROAD',52,90);x.fillStyle='#a9f4df';x.font='24px sans-serif';x.fillText('RIVAL ROUTES / RECORDED CHALLENGE',52,142);x.fillStyle='#fff3d8';x.font='bold 76px sans-serif';x.fillText(lastRun.score.toLocaleString()+' POINTS',52,265);x.font='30px sans-serif';x.fillText(lastRun.success?'75 SECONDS. ONE CLEAN ESCAPE.':lastRun.time.toFixed(1)+' SECONDS ON THE RUN.',52,328);x.fillText(C.worlds[world].name+' / STANDARD DUST DEVIL',52,385);x.fillStyle='#ffb26b';x.font='bold 40px monospace';x.fillText(lastRun.code,52,475);x.fillStyle='#fff3d8';x.font='21px sans-serif';x.fillText('Enter this code in Rival Routes. Local result · unverified.',52,540);c.toBlob(b=>{if(b)download(b,'runroad-challenge.png')})}
function init(){const button=document.createElement('button');button.id='rivalsButton';button.textContent='↗ RIVAL ROUTES';button.onclick=show;document.querySelector('.actions').prepend(button);const d=document.createElement('dialog');d.id='rivalDialog';d.innerHTML=`<form method="dialog"><button class="rival-close" aria-label="Close Rival Routes">✕</button></form><div class="eyebrow">NOBODY DRIVES HOME ALONE</div><h2>RIVAL <em>ROUTES.</em></h2><p>75 seconds. Equal cars. Your friend’s recorded ghost.<br>Asynchronous competition — no live opponents.</p><label for="rivalCode">CHALLENGE CODE</label><input id="rivalCode" maxlength="24" autocomplete="off" spellcheck="false"><button id="rivalNew" class="secondary">CREATE NEW ROUTE</button><label class="rival-import">IMPORT FRIEND’S GHOST (.json)<input id="rivalImport" type="file" accept=".json,application/json"></label><p id="rivalStatus" role="status"></p><button id="rivalStart" class="primary">DRIVE THIS ROUTE ↗</button><small>No account or server. Share codes and ghost files directly. Local results are unverified. Live co-op is planned.</small>`;document.body.append(d);$('rivalNew').onclick=()=>{const values=new Uint32Array(1);crypto.getRandomValues(values);seed=values[0]||1;world=C.world;ghost=null;$('rivalCode').value=code();message('New route ready. Drive it, then export your recorded ghost.')};$('rivalStart').onclick=()=>{try{configure($('rivalCode').value);if(ghost&&ghost.code!==code())ghost=null;d.close();start()}catch(e){message(e.message)}};$('rivalImport').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>120000)throw Error('Ghost file is too large (120 KB maximum).');const run=validate(JSON.parse(await f.text()));ghost=run;const config=parse(run.code);world=config.world;seed=config.seed;$('rivalCode').value=code();message(`Recorded rival loaded: ${run.score.toLocaleString()} points · ${run.time.toFixed(1)}s.`)}catch(e){message('Could not import: '+e.message)}finally{e.target.value=''}};const results=document.createElement('div');results.id='rivalResults';results.hidden=true;results.innerHTML='<button id="rivalShare" class="secondary">SHARE CHALLENGE</button><button id="rivalExport" class="secondary">SAVE GHOST FILE</button><button id="rivalCard" class="secondary">SAVE RESULT CARD</button><p id="rivalResultStatus" role="status"></p>';$('over').append(results);$('rivalShare').onclick=share;$('rivalExport').onclick=()=>{if(lastRun)download(new Blob([JSON.stringify(lastRun)],{type:'application/json'}),'runroad-'+lastRun.code+'.json')};$('rivalCard').onclick=card;}
return{init,begin,capture,finish,draw,random,configure,parse,validate,show,get active(){return active},get seed(){return seed},get world(){return world},mission:()=>({type:'survive',seconds:SECONDS,target:0}),leave(){active=false;if($('rivalResults'))$('rivalResults').hidden=true},hideResults(){if($('rivalResults'))$('rivalResults').hidden=true}};
})();
